import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { ApiConfig } from 'lib/api'
import { dayjs } from 'lib/dayjs'

import * as api from '../../generated/api'
import type { KnowledgeUsageApi } from '../../generated/api.schemas'

export const USAGE_PERIOD_DAYS = [7, 30, 90] as const
export type UsagePeriodDays = (typeof USAGE_PERIOD_DAYS)[number]

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeUsageLogicValues {
    dailyCounts: number[]
    dailyLabels: string[]
    days: UsagePeriodDays
    usage: KnowledgeUsageApi | null
    usageLoadFailed: boolean
    usageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeUsageLogicActions {
    loadUsage: (_: void) => void
    loadUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadUsageSuccess: (
        usage: KnowledgeUsageApi,
        payload?: void
    ) => {
        usage: KnowledgeUsageApi
        payload?: void
    }
    setDays: (days: UsagePeriodDays) => {
        days: 7 | 30 | 90
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeUsageLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        dailyCounts: (usage: KnowledgeUsageApi | null) => number[]
        dailyLabels: (usage: KnowledgeUsageApi | null) => string[]
    }
}

export type businessKnowledgeUsageLogicType = MakeLogicType<
    businessKnowledgeUsageLogicValues,
    businessKnowledgeUsageLogicActions,
    Record<string, any>,
    businessKnowledgeUsageLogicMeta
>

export const businessKnowledgeUsageLogic = kea<businessKnowledgeUsageLogicType>([
    path(['products', 'business_knowledge', 'frontend', 'usage', 'businessKnowledgeUsageLogic']),
    actions({
        setDays: (days: UsagePeriodDays) => ({ days }),
    }),
    loaders(({ values }) => ({
        usage: [
            null as KnowledgeUsageApi | null,
            {
                loadUsage: async (_: void, breakpoint) => {
                    // A period change starts a new request. The breakpoint drops the result
                    // or the failure of the request it replaced, so it cannot land last.
                    try {
                        const usage = await api.businessKnowledgeSourcesUsageRetrieve(
                            String(ApiConfig.getCurrentTeamId()),
                            { days: values.days }
                        )
                        breakpoint()
                        return usage
                    } catch (error) {
                        breakpoint()
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        days: [30 as UsagePeriodDays, { setDays: (_, { days }) => days }],
        usageLoadFailed: [
            false,
            {
                loadUsage: () => false,
                loadUsageSuccess: () => false,
                loadUsageFailure: () => true,
            },
        ],
    }),
    selectors({
        dailyCounts: [
            (s) => [s.usage],
            (usage: KnowledgeUsageApi | null): number[] => (usage?.daily ?? []).map((day) => day.cited_run_count),
        ],
        dailyLabels: [
            (s) => [s.usage],
            (usage: KnowledgeUsageApi | null): string[] =>
                (usage?.daily ?? []).map((day) => dayjs(day.date).format('MMM D')),
        ],
    }),
    listeners(({ actions }) => ({
        setDays: ({ days }) => {
            // pinned: analytics event name. Renaming it breaks dashboards.
            posthog.capture('business knowledge usage period changed', { days })
            actions.loadUsage()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadUsage()
    }),
])
